import { Component, inject, signal } from '@angular/core';
import { CommonModule, DatePipe } from '@angular/common';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { forkJoin } from 'rxjs';
import { SolicitudService } from '../../../shared/services/solicitud.service';
import { TramiteService } from '../../../shared/services/tramite.service';
import { AuthService } from '../../../services/auth.service';
import { semaforoColorClass } from '../../../shared/models/solicitud-status.util';
import { PdfViewerComponent } from '../../../shared/components/pdf-viewer/pdf-viewer.component';
import { BitacoraNotasComponent } from './bitacora-notas/bitacora-notas.component';
import { ChatInversorComponent } from './chat-inversor/chat-inversor.component';
import type { Solicitud } from '../../../shared/models/solicitud.model';
import type { SolicitudTramite } from '../../../shared/models/solicitud.model';

export type TabSeguimiento = 'informacion' | 'documentos' | 'bitacora' | 'chat';

@Component({
  selector: 'app-seguimiento-municipal',
  imports: [CommonModule, DatePipe, RouterLink, PdfViewerComponent, BitacoraNotasComponent, ChatInversorComponent],
  templateUrl: './seguimiento-municipal.component.html',
})
export class SeguimientoMunicipalComponent {
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);
  private readonly solicitudService = inject(SolicitudService);
  private readonly tramiteService = inject(TramiteService);
  protected readonly authService = inject(AuthService);
  protected readonly semaforoColorClass = semaforoColorClass;
  readonly folio: string;
  readonly activeTab = signal<TabSeguimiento>('informacion');
  readonly selectedDocId = signal<number | null>(null);
  readonly mostrarVisor = signal(false);
  readonly loading = signal(true);
  readonly error = signal<string | null>(null);
  readonly solicitud = signal<Solicitud | null>(null);
  readonly tramites = signal<SolicitudTramite[]>([]);

  constructor() {
    this.folio = this.route.snapshot.paramMap.get('folio') ?? '';
    this.cargar();
  }

  private cargar(): void {
    this.loading.set(true);
    forkJoin({
      solicitud: this.solicitudService.getByFolio(this.folio),
      tramites: this.tramiteService.getTramitesAsignados(this.folio),
    }).subscribe({
      next: ({ solicitud, tramites }) => {
        this.solicitud.set(solicitud);
        this.tramites.set(tramites);
        this.loading.set(false);
      },
      error: () => {
        this.loading.set(false);
        this.error.set('No se pudo cargar la información de la solicitud.');
      },
    });
  }

  regresar(): void {
    this.router.navigate(['/ejecutivos/seguimiento-municipal']);
  }

  verDocumento(docId: number): void {
    this.selectedDocId.set(docId);
    this.mostrarVisor.set(true);
  }

  cerrarVisor(): void {
    this.mostrarVisor.set(false);
    this.selectedDocId.set(null);
  }

  tramiteBadgeClass(estado: string): string {
    switch (estado) {
      case 'pendiente': return 'bg-secondary';
      case 'documento_subido': return 'bg-warning text-dark';
      case 'completado': return 'bg-success';
      case 'rechazado': return 'bg-danger';
      default: return 'bg-secondary';
    }
  }
}
